export default class BurningForest {
  grid = new Uint8Array(0);
  nextGrid = new Uint8Array(0);
  width = 0;
  height = 0;
  runtime = null;
  config = {
    treeDensity: 0.55,
    growthProbability: 0.01,
    spreadProbability: 1.0,
    lightningProbability: 0.0002,
    regrowthDelay: 8,
    wrapEdges: true
  };
  age = new Uint8Array(0);

  getApiVersion() {
    return "0.2";
  }

  getConfigSchema() {
    return {
      name: "Горящий лес",
      description: "Модель роста леса и распространения лесного пожара.",
      apiVersion: "0.2",
      params: {
        treeDensity: {
          type: "number",
          default: 0.55,
          label: "Начальная плотность леса",
          description: "Доля клеток, занятых деревьями при создании леса.",
          ui: "scroller",
          min: 0.05,
          max: 1,
          step: 0.05
        },
        growthProbability: {
          type: "number",
          default: 0.01,
          label: "Рост деревьев",
          description: "Вероятность появления дерева на пустой клетке за один шаг.",
          ui: "scroller",
          min: 0,
          max: 0.2,
          step: 0.005
        },
        spreadProbability: {
          type: "number",
          default: 1,
          label: "Распространение огня",
          description: "Вероятность воспламенения дерева от соседнего горящего дерева.",
          ui: "scroller",
          min: 0,
          max: 1,
          step: 0.05
        },
        lightningProbability: {
          type: "number",
          default: 0.0002,
          label: "Молния",
          description: "Вероятность случайного возгорания дерева за один шаг.",
          ui: "scroller",
          min: 0,
          max: 0.01,
          step: 0.0001
        },
        regrowthDelay: {
          type: "number",
          default: 8,
          label: "Восстановление",
          description: "Количество шагов, необходимых выгоревшей клетке перед восстановлением.",
          ui: "scroller",
          min: 0,
          max: 50,
          step: 1
        },
        wrapEdges: {
          type: "boolean",
          default: true,
          label: "Замкнутые границы",
          description: "Считать противоположные края сетки соседними.",
          ui: "checkbox"
        }
      },
      actions: {
        ignite: {
          label: "Поджечь лес",
          description: "Случайно поджечь одно дерево."
        },
        igniteCenter: {
          label: "Поджечь центр",
          description: "Поджечь дерево в центре леса."
        },
        reset: {
          label: "Новый лес",
          description: "Создать новый лес с текущей плотностью деревьев."
        },
        clear: {
          label: "Очистить",
          description: "Удалить все деревья и огонь."
        }
      }
    };
  }

  getConfig() {
    return { ...this.config };
  }

  setConfig(params) {
    const allowed = [
      "treeDensity",
      "growthProbability",
      "spreadProbability",
      "lightningProbability",
      "regrowthDelay",
      "wrapEdges"
    ];

    for (const key of allowed) {
      if (Object.prototype.hasOwnProperty.call(params, key)) {
        this.config[key] = params[key];
      }
    }

    return null;
  }

  init(ctx) {
    this.runtime = ctx.runtime;
    this.width = ctx.gridWidth;
    this.height = ctx.gridHeight;

    const size = this.width * this.height;
    this.grid = new Uint8Array(size);
    this.nextGrid = new Uint8Array(size);
    this.age = new Uint8Array(size);

    this.initializeForest();
  }

  initializeForest() {
    for (let i = 0; i < this.grid.length; i++) {
      this.age[i] = 0;
      this.grid[i] = Math.random() < this.config.treeDensity ? 1 : 0;
    }
  }

  getIndex(x, y) {
    if (this.config.wrapEdges) {
      x = (x + this.width) % this.width;
      y = (y + this.height) % this.height;
      return y * this.width + x;
    }

    if (x < 0 || x >= this.width || y < 0 || y >= this.height) {
      return -1;
    }

    return y * this.width + x;
  }

  hasBurningNeighbor(x, y) {
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) {
          continue;
        }

        const index = this.getIndex(x + dx, y + dy);

        if (index >= 0 && this.grid[index] === 2) {
          if (Math.random() <= this.config.spreadProbability) {
            return true;
          }
        }
      }
    }

    return false;
  }

  iterate(ctx) {
    for (let y = 0; y < this.height; y++) {
      for (let x = 0; x < this.width; x++) {
        const index = y * this.width + x;
        const state = this.grid[index];

        if (state === 0) {
          if (this.age[index] < 255) {
            this.age[index]++;
          }

          if (
            this.age[index] >= this.config.regrowthDelay &&
            Math.random() < this.config.growthProbability
          ) {
            this.nextGrid[index] = 1;
            this.age[index] = 0;
          } else {
            this.nextGrid[index] = 0;
          }
        } else if (state === 1) {
          if (this.hasBurningNeighbor(x, y)) {
            this.nextGrid[index] = 2;
            this.age[index] = 0;
          } else if (Math.random() < this.config.lightningProbability) {
            this.nextGrid[index] = 2;
            this.age[index] = 0;
          } else {
            this.nextGrid[index] = 1;
            this.age[index] = 0;
          }
        } else if (state === 2) {
          this.nextGrid[index] = 0;
          this.age[index] = 0;
        }
      }
    }

    const temp = this.grid;
    this.grid = this.nextGrid;
    this.nextGrid = temp;
  }

  render() {
    return {
      type: "grid",
      width: this.width,
      height: this.height,
      cells: this.grid,
      palette: [
        "#101820",
        "#228B22",
        "#FF4500"
      ]
    };
  }

  runAction(actionId, payload) {
    switch (actionId) {
      case "ignite": {
        const trees = [];

        for (let i = 0; i < this.grid.length; i++) {
          if (this.grid[i] === 1) {
            trees.push(i);
          }
        }

        if (trees.length === 0) {
          this.runtime?.emitEvent({
            type: "warning",
            message: "В лесу нет деревьев для поджигания."
          });
          return;
        }

        const index = trees[Math.floor(Math.random() * trees.length)];
        this.grid[index] = 2;

        this.runtime?.emitEvent({
          type: "info",
          message: "Лес подожжён."
        });
        break;
      }

      case "igniteCenter": {
        const x = Math.floor(this.width / 2);
        const y = Math.floor(this.height / 2);
        const index = this.getIndex(x, y);

        if (index >= 0 && this.grid[index] === 1) {
          this.grid[index] = 2;
          this.runtime?.emitEvent({
            type: "info",
            message: "Центр леса подожжён."
          });
        } else {
          this.runtime?.emitEvent({
            type: "warning",
            message: "В центре нет дерева для поджигания."
          });
        }
        break;
      }

      case "reset": {
        this.initializeForest();
        this.runtime?.emitEvent({
          type: "info",
          message: "Создан новый лес."
        });
        break;
      }

      case "clear": {
        this.grid.fill(0);
        this.nextGrid.fill(0);
        this.age.fill(0);

        this.runtime?.emitEvent({
          type: "info",
          message: "Лес очищен."
        });
        break;
      }
    }
  }

  destroy() {
    this.grid = new Uint8Array(0);
    this.nextGrid = new Uint8Array(0);
    this.age = new Uint8Array(0);
    this.width = 0;
    this.height = 0;
    this.runtime = null;
  }
}
